using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Linq;using UnityEngine;using Newtonsoft.Json;
namespace IslandGame {
 // Development-only capture uses ordinary input commands. It never edits simulation state.
 public sealed class SourceEnvironmentProbe:MonoBehaviour {
  readonly List<object> stages=new List<object>();readonly List<float> frames=new List<float>();readonly HashSet<string> clips=new HashSet<string>();RpgSession session;Battle3DView view;NativeBattle battle;float began;int errors;bool measuring;public bool Finished;string file;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){
   if(!Debug.isDebugBuild||Application.isEditor)return;
   #if UNITY_ANDROID
   try{using(var c=new AndroidJavaClass("com.unity3d.player.UnityPlayer"))using(var a=c.GetStatic<AndroidJavaObject>("currentActivity"))using(var intent=a.Call<AndroidJavaObject>("getIntent")){if(intent.Call<string>("getStringExtra","environment_probe")!="motion")return;var go=new GameObject("Source environment input validation");DontDestroyOnLoad(go);go.AddComponent<SourceEnvironmentProbe>().Begin();}}catch(Exception e){Debug.LogError(e);}
   #endif
  }
  public void Begin(){file=Application.isEditor?Path.GetFullPath(Path.Combine(Application.dataPath,"../../../../../maintenance/cleanup-20261110/evidence/editor-motion.json")):Path.Combine(Application.persistentDataPath,"environment-motion.json");StartCoroutine(Run());}
  void Log(string a,string b,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors++;}
  IEnumerator Run(){Application.logMessageReceived+=Log;while(!(session=FindFirstObjectByType<RpgSession>())||session.State==null)yield return null;session.Auto=false;session.Move=0;while(!MountZoneStream.Current||!MountZoneStream.Current.IsReady)yield return null;view=FindFirstObjectByType<Battle3DView>();battle=FindFirstObjectByType<NativeBattle>();yield return new WaitForSecondsRealtime(.5f);began=Time.realtimeSinceStartup;measuring=true;
   yield return Stage("approach-boundary",1.2f,null,-1);yield return Stage("blocked-run",1.2f,null,-1);yield return Stage("release",.45f,null,0);yield return Stage("run",.7f,null,1);yield return Stage("idle",.5f,null,0);yield return Stage("jump",1.1f,"jump",1);yield return Stage("idle",.35f,null,0);yield return Stage("roll",.75f,"dodge",1);yield return Stage("idle",.65f,null,0);yield return Stage("slide",.65f,"slide",-1);yield return Stage("settled",3,null,0);measuring=false;session.Move=0;session.Auto=false;Save();Finished=true;Application.logMessageReceived-=Log;
  }
  IEnumerator Stage(string name,float seconds,string action,float input){SetStick(input);float startX=(float)session.State["hero"]["x"],sim=(float)session.State["elapsed"],peak=0;int initial=Time.frameCount;var leg=view.HeroTarget?.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name.ToLowerInvariant().Contains("upleg")||t.name.ToLowerInvariant().Contains("thigh"));var q=leg?leg.localRotation:Quaternion.identity;float boneDelta=0;
   float previousX=startX,previousTime=sim,movingSpeed=0,minX=startX,maxX=startX,previousSample=view.HeroSampleTime;int speedSamples=0,poseChanges=0,runFrames=0;if(action!=null){session.Command("tick",new Newtonsoft.Json.Linq.JObject{{action,true},{"x",input},{"y",0}});SetStick(0);}float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end){float sx=(float)session.State["hero"]["x"],st=(float)session.State["elapsed"];if(name=="run"&&st>previousTime&&Mathf.Abs(sx-previousX)>.01f){movingSpeed+=Mathf.Abs(sx-previousX)/100/(st-previousTime);speedSamples++;}minX=Mathf.Min(minX,sx);maxX=Mathf.Max(maxX,sx);if(Mathf.Abs(view.HeroSampleTime-previousSample)>.001f)poseChanges++;previousSample=view.HeroSampleTime;if(view.HeroClipName==view.assets.run.name)runFrames++;previousX=sx;previousTime=st;peak=Mathf.Max(peak,(float)session.State["hero"]["airHeight"]);if(leg)boneDelta=Mathf.Max(boneDelta,Quaternion.Angle(q,leg.localRotation));if(view.HeroClipName!=null)clips.Add(view.HeroClipName);yield return null;}stages.Add(new{name,poseChanges,runFrames,positionSpanMeters=(maxX-minX)/100,camera=battle.CameraRig.Mode.ToString(),finalClip=view.HeroClipName,frames=Time.frameCount-initial,seconds=(float)session.State["elapsed"]-sim,distanceMeters=((float)session.State["hero"]["x"]-startX)/100,peakMeters=peak/100,boneDelta,movingMetersPerSecond=speedSamples>0?movingSpeed/speedSamples:0});
  }
  void SetStick(float input){var stick=FindFirstObjectByType<IslandHudStick>();stick.ResetInput();if(Mathf.Abs(input)<.01f)return;var rect=(RectTransform)stick.transform;var local=rect.rect.center+new Vector2(input*Mathf.Min(rect.rect.width,rect.rect.height)*.45f,0);var e=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){pointerId=200,position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(local))};stick.OnPointerDown(e);}
  void Update(){if(measuring)frames.Add(Time.unscaledDeltaTime*1000);}
  void Save(){var a=frames.OrderBy(x=>x).ToArray();var grass=FindObjectsByType<SourceEnvironmentGrass>(FindObjectsSortMode.None).Where(g=>g.isActiveAndEnabled).Select(g=>new{g.SourceCount,g.VisibleCount,g.DrawCalls}).ToArray();var result=new{version=Application.version,platform=Application.platform.ToString(),resolution=Screen.width+"x"+Screen.height,elapsed=Time.realtimeSinceStartup-began,errors,stages,clips,grass,camera=battle.CameraRig.Mode.ToString(),sun=RenderSettings.sun?.name,networkRequests=session.NetworkRequestCount,local=session.UsesLocalTraining,samples=a.Length,meanMs=a.Length>0?a.Average():0,p95Ms=a.Length>0?a[(int)((a.Length-1)*.95)]:0};File.WriteAllText(file,JsonConvert.SerializeObject(result,Formatting.Indented));}
 }
}
